def transform(grid):
    g=[r[:] for r in grid]
    for r,row in enumerate(grid):
        cells=[(c,x) for c,x in enumerate(row) if x]
        if len(cells)!=2: continue
        (c1,a),(c2,b)=cells
        if a in (1,4,7,8) and b in (1,4,7,8):
            g[r][c2]=0; g[r][c1+1]=b
    return g
